# Central boundary validator for fit_pclv_bayes().
.validate_fit_pclv_inputs <- function(physeq, subject_col, time_col, taxa_vec=NULL, controls) {
 chr1<-function(x,n){if(!is.character(x)||length(x)!=1L||is.na(x)||!nzchar(x))stop(sprintf("`%s` must be a non-missing scalar character value.",n),call.=FALSE);x}; log1<-function(x,n){if(!is.logical(x)||length(x)!=1L||is.na(x))stop(sprintf("`%s` must be a non-missing scalar logical value.",n),call.=FALSE);x}; int1<-function(x,n,lo=1L){if(!is.numeric(x)||length(x)!=1L||!is.finite(x)||x!=floor(x)||x<lo)stop(sprintf("`%s` must be a finite integer >= %d.",n,lo),call.=FALSE);as.integer(x)}; num1<-function(x,n,lo=-Inf,hi=Inf,olo=FALSE,ohi=FALSE){ok<-is.numeric(x)&&length(x)==1L&&is.finite(x);if(ok)ok<-if(olo)x>lo else x>=lo;if(ok)ok<-if(ohi)x<hi else x<=hi;if(!ok)stop(sprintf("`%s` must be a finite scalar in the required range.",n),call.=FALSE);as.numeric(x)}; choice<-function(x,n,v){if(length(x)>1L){if(!identical(x,v))stop(sprintf("`%s` must be a scalar choice.",n),call.=FALSE);x<-x[[1L]]};x<-chr1(x,n);if(!(x%in%v))stop(sprintf("`%s` must be one of: %s.",n,paste(v,collapse=", ")),call.=FALSE);x}
 if(!inherits(physeq,"phyloseq"))stop("`physeq` must inherit from class phyloseq.",call.=FALSE);otu<-tryCatch(phyloseq::otu_table(physeq),error=function(e)NULL);md<-tryCatch(data.frame(phyloseq::sample_data(physeq),check.names=FALSE),error=function(e)NULL);if(is.null(otu)||is.null(md)||!phyloseq::ntaxa(physeq)||!phyloseq::nsamples(physeq))stop("`physeq` must contain a non-empty OTU table and sample metadata.",call.=FALSE);mat<-as(otu,"matrix");if(!phyloseq::taxa_are_rows(physeq))mat<-t(mat);sn<-phyloseq::sample_names(physeq);tn<-phyloseq::taxa_names(physeq);if(length(sn)!=ncol(mat)||anyNA(sn)||any(!nzchar(sn))||anyDuplicated(sn))stop("`physeq` sample names must be present, unique, and match OTU columns.",call.=FALSE);if(length(tn)!=nrow(mat)||anyNA(tn)||any(!nzchar(tn))||anyDuplicated(tn))stop("`physeq` taxa names must be present, unique, and match OTU rows.",call.=FALSE);if(!identical(colnames(mat),sn)||!identical(rownames(mat),tn)||nrow(md)!=length(sn)||!setequal(rownames(md),sn))stop("`physeq` OTU and sample-metadata dimensions or names are inconsistent.",call.=FALSE);if(!is.numeric(mat)||any(!is.finite(mat))||any(mat<0))stop("`physeq` abundance values must be numeric, finite, and nonnegative.",call.=FALSE)
 subject_col<-chr1(subject_col,"subject_col");time_col<-chr1(time_col,"time_col");miss<-setdiff(c(subject_col,time_col),names(md));if(length(miss))stop(sprintf("Missing sample metadata column(s): %s.",paste(miss,collapse=", ")),call.=FALSE);subject<-md[[subject_col]];if(!length(subject)||anyNA(subject)||any(!nzchar(as.character(subject))))stop(sprintf("`%s` subject values must be present and non-missing.",subject_col),call.=FALSE);traw<-md[[time_col]];time<-if(is.numeric(traw))as.numeric(traw)else suppressWarnings(as.numeric(as.character(traw)));if(length(time)!=nrow(md)||any(!is.finite(time)))stop(sprintf("`%s` time values must be numeric or safely coercible and finite.",time_col),call.=FALSE);dup<-names(Filter(function(z)anyDuplicated(z),split(time,as.character(subject))));if(length(dup))stop(sprintf("Duplicate time values detected within subject(s): %s.",paste(dup,collapse=", ")),call.=FALSE)
 if(is.null(taxa_vec))taxa_vec<-tn;if(!is.character(taxa_vec)||!length(taxa_vec)||anyNA(taxa_vec)||any(!nzchar(taxa_vec))||anyDuplicated(taxa_vec))stop("`taxa_vec` must be NULL or a non-empty unique character vector.",call.=FALSE);unknown<-setdiff(taxa_vec,tn);if(length(unknown))stop(sprintf("Unknown taxa requested: %s.",paste(unknown,collapse=", ")),call.=FALSE);if(length(taxa_vec)<2L)stop("`taxa_vec` must contain at least two taxa.",call.=FALSE)
 for(n in c("alr_spline_cv","quiet","silent_sampler","use_pathfinder_init","pf_psis_resample"))controls[[n]]<-log1(controls[[n]],n);mins<-c(chains=1L,iter_warmup=0L,iter_sampling=1L,seed=0L,progress_every=1L,n_workers_outer=1L,kfold_K=2L,kfold_R=1L,kfold_seed=0L,n_workers_kfold=1L,max_retries=0L,pf_num_paths=1L,pf_draws=1L,pf_history_size=1L,pf_max_lbfgs_iters=1L,min_unique_times=3L,min_pairs=1L,max_treedepth=1L);for(n in names(mins))controls[[n]]<-int1(controls[[n]],n,mins[[n]]);controls$adapt_delta<-num1(controls$adapt_delta,"adapt_delta",0,1,TRUE,TRUE);for(n in c("eps","minpos_alpha","eps_fixed","lib_eps_c","rest_floor_frac"))controls[[n]]<-num1(controls[[n]],n,0,Inf,TRUE);controls$nz_partner_min_frac<-num1(controls$nz_partner_min_frac,"nz_partner_min_frac",0,1);controls$rest_floor_frac<-num1(controls$rest_floor_frac,"rest_floor_frac",0,1);if(!is.null(controls$alr_spline_df)||!is.null(controls$alr_spline_spar)||!isTRUE(controls$alr_spline_cv))stop("Canonical CV smoothing requires `alr_spline_df = NULL`, `alr_spline_spar = NULL`, and `alr_spline_cv = TRUE`.",call.=FALSE);controls$zero_mode_alr<-choice(controls$zero_mode_alr,"zero_mode_alr",c("minpos_time","minpos_subject","lib","fixed"));controls$minpos_base<-choice(controls$minpos_base,"minpos_base",c("ij","triplet"));controls$smooth_scale<-choice(controls$smooth_scale,"smooth_scale",c("logra","alr"));controls$progress<-choice(controls$progress,"progress",c("bar","verbose","none"));controls$metric<-choice(controls$metric,"metric",c("diag_e","dense_e","unit_e"));if(controls$kfold_K>length(unique(as.character(subject))))stop("`kfold_K` cannot exceed the number of unique subjects.",call.=FALSE)
 init<-controls$init;valid_init<-is.null(init)||is.function(init)||(is.numeric(init)&&length(init)==1L&&is.finite(init))||inherits(init,"CmdStanPathfinder")||is.environment(init)||(is.list(init)&&length(init)>0L);if(!valid_init)stop("`init` is malformed or unsupported.",call.=FALSE);if(is.list(init)&&!is.function(init)){per_chain<-is.list(init[[1L]]);if(per_chain&&(length(init)!=controls$chains||any(vapply(init,function(z)!length(z),logical(1)))))stop("`init` per-chain list must contain one non-empty entry per chain.",call.=FALSE);if(!per_chain&&(is.null(names(init))||any(!nzchar(names(init)))))stop("`init` must be a named parameter list.",call.=FALSE)};meta_df<-data.frame(Sample=rownames(md),subject=subject,time=time,stringsAsFactors=FALSE);meta_df<-meta_df[order(as.character(meta_df$subject),meta_df$time),,drop=FALSE];rownames(meta_df)<-NULL;list(meta_df=meta_df,mat_rel=mat,taxa_vec=taxa_vec,subject_col=subject_col,time_col=time_col,controls=controls)
}
